package com.rpb.reservation.workforce.calendar.annual;
import static com.rpb.reservation.workforce.calendar.annual.HolidayDtos.*;
import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service @Transactional(readOnly=true)
public class PublicHolidayService {
 private final WorkforceAccess access;private final HolidayYearRepository repository;private final WorkforceAudit audit;
 public PublicHolidayService(WorkforceAccess access,HolidayYearRepository repository,WorkforceAudit audit){this.access=access;this.repository=repository;this.audit=audit;}
 private void year(int year){if(year<2000||year>2100)throw WorkforceException.invalid();}
 public YearPage get(CurrentActor actor,UUID store,int year){access.enter(actor,store);year(year);return new YearPage(year,repository.version(actor.tenantId(),year),repository.rows(actor.tenantId(),year,false).stream().map(Stored::holiday).toList());}
 public Template template(CurrentActor actor,UUID store,int year){access.enter(actor,store);year(year);var template=SingaporeHolidayTemplates.forYear(year);return new Template(year,template.source(),template.items().stream().map(h->new Holiday(UUID.nameUUIDFromBytes((actor.tenantId()+":"+h.id()).getBytes(java.nio.charset.StandardCharsets.UTF_8)),h.date(),h.name(),h.englishName(),h.observedOn(),h.observedKind(),h.enabled(),h.tentative())).toList());}
 @Transactional public YearPage save(CurrentActor actor,UUID store,int year,Write input){access.sourceWrite(actor);access.enter(actor,store);access.headOffice(actor);year(year);if(input==null||input.expectedVersion()==null||input.expectedVersion()<0||input.items()==null||input.items().size()>100)throw WorkforceException.invalid();var normalized=new ArrayList<Holiday>();var ids=new HashSet<UUID>();for(var h:input.items()){if(h==null||h.id()==null||!ids.add(h.id())||h.date()==null||h.date().getYear()!=year||h.name()==null||h.name().isBlank()||h.name().trim().length()>100||h.englishName()!=null&&h.englishName().trim().length()>100||h.enabled()==null||h.tentative()==null||!Set.of("none","official","agreed").contains(h.observedKind()==null?"":h.observedKind())||h.observedOn()==null&&!h.observedKind().equals("none")||h.observedOn()!=null&&(h.observedKind().equals("none")||!h.observedOn().isAfter(h.date())||h.observedOn().isAfter(h.date().plusDays(365))))throw WorkforceException.invalid();normalized.add(new Holiday(h.id(),h.date(),h.name().trim(),h.englishName()==null?"":h.englishName().trim(),h.observedOn(),h.observedKind(),h.enabled(),h.tentative()));}normalized.sort(Comparator.comparing(Holiday::date).thenComparing(Holiday::name).thenComparing(Holiday::id));repository.lock(actor.tenantId());repository.lockCalendars(actor.tenantId());var old=get(actor,store,year);if(old.items().equals(normalized)&&(input.expectedVersion()==old.version()||input.expectedVersion()+1==old.version()))return old;if(old.version()!=input.expectedVersion())throw WorkforceException.conflict();repository.save(actor.tenantId(),year,old.version()+1,normalized);var result=get(actor,store,year);audit.changed(actor,store,"holiday-year.save",null,old,result);return result;}
}
